import sqlite3 from 'better-sqlite3';
import bcrypt from 'bcryptjs';
import { randomBytes } from 'crypto';

const app = express();
app.use(express.json());

const SECRET_KEY = process.env.SECRET_KEY || randomBytes(32).toString('hex');
